/* Shared chrome. Keep its DOM stable while replacing business content. */
(function(){const previous=render;let sidebar=null,header=null,main=null,scrolls=new Map;function key(){return selected?'project:'+selected+':'+tab:page}
let lastKey=null;render=function(){if(main&&lastKey){const sc=main.querySelector('.workspace-scroll,.tablewrap,.daily-list');if(sc)scrolls.set(lastKey,sc.scrollTop)}previous();const home=page==='工作台'&&!selected,root=document.querySelector('#app>div');if(!root)return;const generatedSide=root.querySelector(':scope>aside'),generatedMain=root.querySelector(':scope>main');if(!generatedMain)return;const generatedHeader=generatedMain.querySelector(':scope>header'),content=generatedMain.querySelector(':scope>.content,:scope>.v4-content');if(!content)return;
if(!sidebar){sidebar=document.createElement('aside');sidebar.className='unified-sidebar';sidebar.innerHTML='<button class="unified-brand" aria-label="回到数据总览"><img class="unified-logo ink-logo" src="brand-yantai/mark.svg" alt=""><b>砚台泼墨</b></button><nav aria-label="主导航"></nav><div class="unified-side-bottom"><button data-dest="设置" aria-label="设置与备份"><span class="shell-symbol">⚙</span><span>设置与备份</span></button><div class="unified-person"><span>我</span><div>个人工作空间<small>本地工作空间</small></div></div></div>';const items=[['工作台','数据总览','▦'],['项目台账','项目台账','▣'],['待办与风险','今日工作','☷'],['资料知识库','资料库','▤']];sidebar.querySelector('nav').innerHTML=items.map(([dest,label,symbol])=>`<button data-dest="${dest}" aria-label="${label}"><span class="shell-symbol" aria-hidden="true">${symbol}</span><span>${label}</span>${dest==='项目台账'?'<small class="shell-count"></small>':''}</button>`).join('');sidebar.querySelectorAll('[data-dest]').forEach(b=>b.onclick=()=>nav(b.dataset.dest));sidebar.querySelector('.unified-brand').onclick=()=>nav('工作台')}
if(!header){header=document.createElement('header');header.className='unified-header';header.innerHTML='<div class="unified-crumb"><span>工作空间</span><span>/</span><b></b></div><div class="unified-header-right"><span class="shell-date"></span><span class="shell-avatar">我</span></div>'}
if(!main){main=document.createElement('main');main.className='unified-main'}else main.replaceChildren();const label=selected?'项目台账 / '+getp(selected).name:({'工作台':'数据总览','待办与风险':'今日工作','资料知识库':'资料库','设置':'设置与备份'}[page]||page);header.querySelector('b').textContent=label;header.querySelector('.shell-date').textContent=today().replaceAll('-',' / ');sidebar.querySelectorAll('[data-dest]').forEach(b=>{const active=selected?b.dataset.dest==='项目台账':b.dataset.dest===page;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});sidebar.querySelector('.shell-count').textContent=data.projects.length;
// Move the existing overview controls into its title row with handlers intact.
if(home){const actions=generatedHeader?.querySelector('.v4-top-actions');if(actions){actions.classList.add('shell-overview-actions');content.querySelector('.v4-heading')?.append(actions)}}
main.append(header,content);root.replaceChildren(sidebar,main);root.className='unified-layout';root.classList.toggle('unified-overview',home);content.classList.add('unified-content');if(!selected&&page==='设置'){const title=content.querySelector('.heading h1');if(title)title.textContent='设置与备份';content.querySelector('.heading .actions')?.remove()}lastKey=key();const sc=content.querySelector('.workspace-scroll,.tablewrap,.daily-list');if(sc&&scrolls.has(lastKey))sc.scrollTop=scrolls.get(lastKey);
};})();
